#!/usr/bin/env bash
# PERF_DRILL_V2 deploy — Performans marka drill'i ZAMAN SECICIYE uyar.
#   (1) backend GET /api/bi/marka-kirilim (donem markalari)  (2) guncel kokpit2.html (async donem-farkinda drill, %'ye gore sirali).
#   CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok"; exit 1; }
TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"; echo "yedek: $SRV.bak.$TS"
printf '%s' '' | base64 -d > /tmp/patch_marka_kirilim.py
python3 /tmp/patch_marka_kirilim.py "$SRV"
if ! node --check "$SRV"; then echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1; fi
echo "node --check: OK"
cp shells/kokpit2.html "shells/kokpit2.html.bak.$TS"
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "kokpit2.html satir: $(wc -l < shells/kokpit2.html)"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
docker exec krb-assessment sh -c "grep -c 'marka-kirilim' /app/server.mjs" || true
echo "== ONIZLE: /api/bi/kokpit2 -> Performans kartina tikla; secici (Bu ay/3/6/12/Yil Basi) degistir -> marka dagilimi doneme uyar, %'ye gore sirali =="
echo "== DONE =="
